update public.simulations set brief = 'Tình huống: Local Brand thời trang bán qua Fanpage (18.000 follower) và Shopee, sắp ra mắt BST Thu-Đông cho sinh viên (hoodie “Campus Fleece”). Engagement rate giảm 30% (3,0% → 2,1%); 10 bài gần nhất là ảnh sản phẩm nền trắng, chưa có kế hoạch nội dung và video ngắn.

Ràng buộc: team 2 người, không thuê KOL/studio, quay bằng điện thoại; khách hàng Gen Z 18–22 tuổi.',
  task_instructions = '## Bối cảnh

Tình huống: Local Brand thời trang bán qua Fanpage (18.000 follower) và Shopee, sắp ra mắt BST Thu-Đông cho sinh viên (hoodie “Campus Fleece”). Engagement rate giảm 30% (3,0% → 2,1%); 10 bài gần nhất là ảnh sản phẩm nền trắng, chưa có kế hoạch nội dung và video ngắn.

Ràng buộc: team 2 người, không thuê KOL/studio, quay bằng điện thoại; khách hàng Gen Z 18–22 tuổi.

## Yêu cầu nhiệm vụ

1. Kế hoạch nội dung 7 ngày dạng bảng (Ngày – Kênh – Định dạng – Ý tưởng – Mục tiêu – CTA)

2. 01 bài copywriting Facebook ≤150 từ đúng Brand Voice

3. 02 kịch bản TikTok/Reels 30s bắt trend, nêu trend và lý do chọn.',
  is_available = true,
  unavailable_reason = null,
  rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":15,"maxScore":15}]'::jsonb,
  grading_rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C1-1\",\"text\":\"Kế hoạch 7 ngày đủ 3 giai đoạn (teaser → ra mắt → duy trì), mỗi ngày có kênh – định dạng – mục tiêu – CTA\",\"points\":15,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-01-C1-2\",\"text\":\"Copy đúng Product Brief: chất liệu, giá, ưu đãi 48 giờ\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-01-C1-3\",\"text\":\"· 02 kịch bản 30s: hook trong 3 giây đầu, đủ cảnh – lời – text overlay, có CTA\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C2-1\",\"text\":\"Mỗi lựa chọn (định dạng, trend, giờ đăng) giải thích bằng insight Gen Z sinh viên, gắn với nguyên nhân sụt tương tác (nội dung đơn điệu, thiếu video ngắn); nêu KPI kỳ vọng (VD: engagement rate ≥3,5%, lượt xem video)\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C3-1\",\"text\":\"Ưu đãi chỉ 48 giờ nhưng kế hoạch 7 ngày → ngày 4–7 chuyển sang social proof/UGC/review · Trend lệch tông hoặc rủi ro bản quyền nhạc → chỉnh cho hợp giọng “Shop – Cậu”, dùng nhạc thư viện thương mại · Nguồn lực hạn chế (không KOL, quay bằng điện thoại) → kịch bản đơn giản, khả thi\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C4-1\",\"text\":\"Đủ 3 yêu cầu đúng thứ tự, dùng bảng/gạch đầu dòng rõ ràng, văn phong chuyên nghiệp, hoàn thành trong 60 phút\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":15,"maxScore":15}]'::jsonb,
