update public.simulations set brief = 'Tình huống: Trung tâm tiếng Anh giao tiếp, mục tiêu 100 lead trong 14 ngày. 3 ngày đầu chi 5.000.000đ, hiển thị 62.500 (CPM 80.000đ), 500 lượt nhấp (CTR 0,8%, CPC 10.000đ), 8 lead (chuyển đổi 1,6%), CPL 625.000đ so với mục tiêu tối đa 200.000đ.

Ngân sách còn lại: 15.000.000đ cho 11 ngày tiếp theo.',
  task_instructions = '## Bối cảnh

Tình huống: Trung tâm tiếng Anh giao tiếp, mục tiêu 100 lead trong 14 ngày. 3 ngày đầu chi 5.000.000đ, hiển thị 62.500 (CPM 80.000đ), 500 lượt nhấp (CTR 0,8%, CPC 10.000đ), 8 lead (chuyển đổi 1,6%), CPL 625.000đ so với mục tiêu tối đa 200.000đ.

Ngân sách còn lại: 15.000.000đ cho 11 ngày tiếp theo.

## Yêu cầu nhiệm vụ

1. Chỉ ra 3 nguyên nhân CPL cao, dẫn chứng bằng số liệu

2. Đề xuất tối ưu: A/B test Target, Creative, Landing Page (giả thuyết, biến thử, chỉ số đo, tiêu chí chọn bên thắng)

3. Bảng phân bổ 15.000.000đ theo giai đoạn (ngân sách, nhóm quảng cáo, KPI lead/CPL), nêu giả định để đủ 100 lead.',
  is_available = true,
  unavailable_reason = null,
  rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":15,"maxScore":15}]'::jsonb,
  grading_rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"checklist_id\":\"MKT-02-C1-1\",\"text\":\"3 nguyên nhân gốc kèm số liệu :\\n(a) targeting quá rộng – nhóm A tiêu 60% ngân sách, CPL 1.000.000đ so với nhóm B 400.000đ;\\n(b) creative yếu – CTR chung 0,8%, nhóm A 0,6%;\\n(c) landing page/form – chuyển đổi 1,6%, tải 5,2 giây, form 7 trường\",\"points\":15,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-02-C1-2\",\"text\":\"Tính đúng CPL mục tiêu: 15.000.000 ÷ 92 lead ≈ 163.000đ\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-02-C1-3\",\"text\":\"Phương án A/B test hợp lý, phân bổ cộng đúng 15.000.000đ\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","description":"{\"checklist\":[{\"checklist_id\":\"MKT-02-C2-1\",\"text\":\"Mỗi nguyên nhân gắn chỉ số cụ thể; mỗi A/B test có giả thuyết, 1 biến/lần, chỉ số đo, ngưỡng quyết định; giải thích cách chia ngân sách\\nVD: 20% (3.000.000đ) test 2 ngày; 80% (12.000.000đ) dồn nhóm thắng, CPL kỳ vọng ≈150.000đ → ~80 lead, cộng ~10 lead từ test và 8 lead đã có ≈ 98–100.\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","description":"{\"checklist\":[{\"checklist_id\":\"MKT-02-C3-1\",\"text\":\"- Giữ CPL 200.000đ chỉ đạt 75 + 8 = 83 lead < 100 → cải thiện đồng thời CTR/CVR, thêm kênh bổ trợ (retarget, Zalo OA, giới thiệu bạn bè) hoặc báo quản lý điều chỉnh mục tiêu\\n- Giai đoạn test tốn ngân sách chưa ra lead → ngân sách test nhỏ, quy tắc dừng sớm nhóm kém\\n- CPL thấp nhưng lead rác → thêm câu hỏi sàng lọc, theo dõi tỷ lệ liên lạc được\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"checklist_id\":\"MKT-02-C4-1\",\"text\":\"Đủ 3 yêu cầu đúng thứ tự, bảng phân bổ ngân sách rõ ràng, dùng đúng thuật ngữ ads (CPL, CTR, CVR, CPM), hoàn thành trong 60 phút\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":15,"maxScore":15}]'::jsonb,
  reference_data = '{"position_id":"MKT-02","position_name":"Digital Marketing Executive (Chuyên viên Marketing Số)","level":"Fresher/Junior","time_limit_minutes":60,"time_limit_source":"specified","source_version":"20261019","source_policy":"document_with_authorized_supplements","content_revision":"20261019-simulations","source_block":291,"context":"Tình huống: Trung tâm tiếng Anh giao tiếp, mục tiêu 100 lead trong 14 ngày. 3 ngày đầu chi 5.000.000đ, hiển thị 62.500 (CPM 80.000đ), 500 lượt nhấp (CTR 0,8%, CPC 10.000đ), 8 lead (chuyển đổi 1,6%), CPL 625.000đ so với mục tiêu tối đa 200.000đ.\n\nNgân sách còn lại: 15.000.000đ cho 11 ngày tiếp theo.","requirements":["1. Chỉ ra 3 nguyên nhân CPL cao, dẫn chứng bằng số liệu","2. Đề xuất tối ưu: A/B test Target, Creative, Landing Page (giả thuyết, biến thử, chỉ số đo, tiêu chí chọn bên thắng)","3. Bảng phân bổ 15.000.000đ theo giai đoạn (ngân sách, nhóm quảng cáo, KPI lead/CPL), nêu giả định để đủ 100 lead."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":35,"description":"3 nguyên nhân gốc kèm số liệu (15):\n(a) targeting quá rộng – nhóm A tiêu 60% ngân sách, CPL 1.000.000đ so với nhóm B 400.000đ;\n(b) creative yếu – CTR chung 0,8%, nhóm A 0,6%;\n(c) landing page/form – chuyển đổi 1,6%, tải 5,2 giây, form 7 trường · Tính đúng CPL mục tiêu: 15.000.000 ÷ 92 lead ≈ 163.000đ (10) · Phương án A/B test hợp lý, phân bổ cộng đúng 15.000.000đ (10)","checklist":[{"checklist_id":"MKT-02-C1-1","text":"3 nguyên nhân gốc kèm số liệu :\n(a) targeting quá rộng – nhóm A tiêu 60% ngân sách, CPL 1.000.000đ so với nhóm B 400.000đ;\n(b) creative yếu – CTR chung 0,8%, nhóm A 0,6%;\n(c) landing page/form – chuyển đổi 1,6%, tải 5,2 giây, form 7 trường","points":15,"scoring_source":"ai"},{"checklist_id":"MKT-02-C1-2","text":"Tính đúng CPL mục tiêu: 15.000.000 ÷ 92 lead ≈ 163.000đ","points":10,"scoring_source":"ai"},{"checklist_id":"MKT-02-C1-3","text":"Phương án A/B test hợp lý, phân bổ