update public.simulation_attempts a set superseded_at = now() from public.simulations s where a.simulation_id = s.id and s.id = 'e0f08d10-acc9-58fe-8a27-aa9625092067' and a.submission_id is null and a.superseded_at is null and coalesce(s.reference_data->>'content_revision', '') <> '20261019-simulations';
update public.simulations set brief = 'Tình huống: Công ty SaaS quản lý bán hàng F&B vừa và nhỏ sắp ra mắt tính năng “Tự động quản lý nguyên vật liệu & cảnh báo tồn kho”. Organic traffic ~1.200 lượt/tháng (chủ yếu tìm tên thương hiệu), blog 8 bài chủ yếu là tin công ty, website yếu về uy tín tìm kiếm (DR ≈12).

Mục tiêu & nguồn lực: 5.000 lượt organic/tháng và 100 lead dùng thử/tháng trong 3 tháng; 1 người viết, 6 bài/tháng.',
  task_instructions = '## Bối cảnh

Tình huống: Công ty SaaS quản lý bán hàng F&B vừa và nhỏ sắp ra mắt tính năng “Tự động quản lý nguyên vật liệu & cảnh báo tồn kho”. Organic traffic ~1.200 lượt/tháng (chủ yếu tìm tên thương hiệu), blog 8 bài chủ yếu là tin công ty, website yếu về uy tín tìm kiếm (DR ≈12).

Mục tiêu & nguồn lực: 5.000 lượt organic/tháng và 100 lead dùng thử/tháng trong 3 tháng; 1 người viết, 6 bài/tháng.

## Yêu cầu nhiệm vụ

1. Kế hoạch nội dung 1 tháng theo phễu TOFU – MOFU – BOFU, 6 chủ đề (Tuần – Giai đoạn phễu – Chủ đề – Từ khóa chính – Nỗi đau – CTA)

2. Chọn 5 từ khóa SEO từ bảng 12 từ khóa và giải thích

3. 01 bài MOFU chuẩn SEO ~500–600 từ kèm title tag, meta description, H1, H2, CTA mềm.',
  is_available = true,
  unavailable_reason = null,
  rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":15,"maxScore":15}]'::jsonb,
  grading_rubric = '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"checklist_id\":\"MKT-03-C1-1\",\"text\":\"Kế hoạch 1 tháng có 6 chủ đề phân bổ hợp lý trên phễu, mỗi chủ đề gắn nỗi đau chủ quán\",\"points\":12,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-03-C1-2\",\"text\":\"5 từ khóa đúng đối tượng, đúng intent, khả thi với DR thấp, ưu tiên KD ≤30\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-03-C1-3\",\"text\":\"Bài MOFU đủ on-page: title tag ≤60 ký tự, meta ≤155 ký tự, H1, ≥2 H2, từ khóa chính ở đoạn mở đầu, CTA mềm\",\"points\":13,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","description":"{\"checklist\":[{\"checklist_id\":\"MKT-03-C2-1\",\"text\":\"Giải thích vai trò từng chủ đề trong phễu; chọn từ khóa dựa trên volume, KD, intent; bài viết giải quyết đúng nỗi đau (thất thoát, hết hàng giờ cao điểm) rồi dẫn tới tính năng tự nhiên\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","description":"{\"checklist\":[{\"checklist_id\":\"MKT-03-C3-1\",\"text\":\"- Từ khóa volume cao nhưng sai đối tượng/KD cao → ưu tiên từ khóa nhỏ, intent rõ, dễ lên top; nêu trade-off\\n- Tính năng chưa ra mắt, chưa có case study → không bịa số liệu, dùng ví dụ minh họa rõ ràng\\n- Nguồn lực 1 người, 6 bài/tháng → sắp thứ tự xuất bản, internal link TOFU → MOFU → BOFU, tái sử dụng nội dung\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"checklist_id\":\"MKT-03-C4-1\",\"text\":\"Đủ 3 yêu cầu đúng thứ tự, kế hoạch dạng bảng, bài viết có heading rõ ràng, hoàn thành trong 60 phút\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":15,"maxScore":15}]'::jsonb,
  reference_data = '{"position_id":"MKT-03","position_name":"Content Marketing Specialist (Chuyên viên Sáng tạo Nội dung)","level":"Fresher/Junior","time_limit_minutes":60,"time_limit_source":"specified","source_version":"20261019","source_policy":"document_with_authorized_supplements","content_revision":"20261019-simulations","source_block":297,"context":"Tình huống: Công ty SaaS quản lý bán hàng F&B vừa và nhỏ sắp ra mắt tính năng “Tự động quản lý nguyên vật liệu & cảnh báo tồn kho”. Organic traffic ~1.200 lượt/tháng (chủ yếu tìm tên thương hiệu), blog 8 bài chủ yếu là tin công ty, website yếu về uy tín tìm kiếm (DR ≈12).\n\nMục tiêu & nguồn lực: 5.000 lượt organic/tháng và 100 lead dùng thử/tháng trong 3 tháng; 1 người viết, 6 bài/tháng.","requirements":["1. Kế hoạch nội dung 1 tháng theo phễu TOFU – MOFU – BOFU, 6 chủ đề (Tuần – Giai đoạn phễu – Chủ đề – Từ khóa chính – Nỗi đau – CTA)","2. Chọn 5 từ khóa SEO từ bảng 12 từ khóa và giải thích","3. 01 bài MOFU chuẩn SEO ~500–600 từ kèm title tag, meta description, H1, H2, CTA mềm."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":35,"description":"- Kế hoạch 1 tháng có 6 chủ đề phân bổ hợp lý trên phễu, mỗi chủ đề gắn nỗi đau chủ quán (12)\n- 5 từ khóa đúng đối tượng, đúng intent, khả thi với DR thấp, ưu tiên KD ≤30 (10)\n- Bài MOFU đủ on-page: title tag ≤60 ký tự, meta ≤155 ký tự, H1, ≥2 H2, từ khóa chính ở đoạn mở đầu, CTA mềm (13)\nVD: TOFU “Cách tính giá vốn đồ uống”; MOFU “Cách quản lý nguyên liệu quán cafe không thất thoát”, “Định mức nguyên liệu pha chế”; BOFU “Phần mềm quản lý kho F&B: cảnh báo tồn tự động”. Loại “công thức pha chế trà sữa”, “mở quán cafe cần chuẩn bị gì”","checklist":[{"checklist_id":"MKT-03-C1-1","text":"Kế hoạch 1 tháng có 6 chủ đề phân bổ hợp lý trên phễu, mỗi chủ đề gắn nỗi đau chủ quán","points":12,"scoring_source":"ai"},{"checklist_id":"MKT-03-C1-2","text":"5 từ khóa đúng đối tượng, đúng intent, khả thi với DR thấp, ưu tiên K