update public.simulations set brief = 'Bạn là Chuyên viên Thẩm định Tín dụng SME tại Ngân hàng TMCP Đại Dương. CTCP Con Sứa đề nghị vay 5 tỷ đồng để mua dây chuyền. Trưởng phòng yêu cầu bạn hoàn thành tờ trình thẩm định tín dụng trước cuộc họp thẩm định, dựa trên hồ sơ được cung cấp.

- Thông tin doanh nghiệp

- Lịch sử tín dụng

- Báo cáo tài chính 2023–2025

- Tài sản đảm bảo đề xuất

- Phương án sử dụng vốn

- Chính sách tín dụng SME của Ngân hàng Đại Dương',
  task_instructions = '## Bối cảnh

Bạn là Chuyên viên Thẩm định Tín dụng SME tại Ngân hàng TMCP Đại Dương. CTCP Con Sứa đề nghị vay 5 tỷ đồng để mua dây chuyền. Trưởng phòng yêu cầu bạn hoàn thành tờ trình thẩm định tín dụng trước cuộc họp thẩm định, dựa trên hồ sơ được cung cấp.

- Thông tin doanh nghiệp

- Lịch sử tín dụng

- Báo cáo tài chính 2023–2025

- Tài sản đảm bảo đề xuất

- Phương án sử dụng vốn

- Chính sách tín dụng SME của Ngân hàng Đại Dương

## Yêu cầu nhiệm vụ

Nhiệm vụ 1: Điền vào Bảng Thẩm định cho sẵn và Đánh giá chất lượng dòng tiền của doanh nghiệp

Nhiệm vụ 2: Đánh giá khả năng trả nợ, nguồn trả nợ, và đối chiếu khoản vay với chính sách tín dụng của Ngân hàng. Xác định 3 rủi ro tín dụng trọng yếu nhất, xếp theo mức độ quan trọng.

Nhiệm vụ 3: Quyết định Có/Không cấp tín dụng. Nếu có, đề xuất cụ thể: hạn mức, kỳ hạn, lãi suất và điều kiện đi kèm. Nếu không, nêu lý do và điều kiện để Ngân hàng xem xét lại.',
  is_available = true,
  unavailable_reason = null,
  rubric = '[{"id":"C1","label":"NHIỆM VỤ 1 –","weight":35,"maxScore":35},{"id":"C2","label":"NHIỆM VỤ 2 –","weight":25,"maxScore":25},{"id":"C3","label":"NHIỆM VỤ 3 -","weight":30,"maxScore":30},{"id":"C4","label":"TRÌNH BÀY","weight":10,"maxScore":10}]'::jsonb,
  grading_rubric = '[{"id":"C1","label":"NHIỆM VỤ 1 –","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-02-C1-1\",\"text\":\"- Tính 5 chỉ số × 3 năm (20đ): 4đ/chỉ số khi đúng cả 3 năm; đúng 2/3 năm 2,5đ; 1/3 năm 1đ; sai công thức nhưng nhất quán tối đa 50%.\",\"points\":20,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-02-C1-2\",\"text\":\"- Đánh giá đúng chất lượng dòng tiền (15đ)\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"NHIỆM VỤ 2 –","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-02-C2-1\",\"text\":\"- Khả năng trả nợ & tuân thủ chính sách (10đ): Đánh giá proforma vay 5 tỷ qua D/E, ICR, Nợ vay/EBITDA, tỷ lệ tài trợ và TSBĐ; so sánh phương án vay 3 tỷ.\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-02-C2-2\",\"text\":\"- Nêu 3 rủi ro có số liệu, xếp theo mức độ ưu tiên (15đ)\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"NHIỆM VỤ 3 -","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-02-C3-1\",\"text\":\"- Quyết định tín dụng (20đ): Quyết định cho vay/từ chối nhất quán với phân tích. Thiếu giải thích: tối đa 5đ\\n+ Cấp tín dụng: Đề xuất hạn mức ≤ 4,9 tỷ, kỳ hạn ≤ 60 tháng, ân hạn khoảng 12 tháng, lãi suất 9–10% và nguồn trả nợ.\\n+ Từ chối, nêu căn cứ và lộ trình xem xét lại.\",\"points\":20,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-02-C3-2\",\"text\":\"- Điều kiện kèm theo (10đ): Đề xuất ít nhất 4 điều kiện phù hợp với rủi ro\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C4","label":"TRÌNH BÀY","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-02-C4-1\",\"text\":\"TRÌNH BÀY (10đ)\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10}]'::jsonb,
  reference_data = '{"position_id":"TCNH-02","position_name":"Credit Analyst (Chuyên viên Thẩm định Tín dụng)","level":"Fresher/Junior","time_limit_minutes":60,"time_limit_source":"not_specified","source_version":"20261019","source_policy":"document_only","content_revision":"20261019-simulations","source_block":441,"context":"Bạn là Chuyên viên Thẩm định Tín dụng SME tại Ngân hàng TMCP Đại Dương. CTCP Con Sứa đề nghị vay 5 tỷ đồng để mua dây chuyền. Trưởng phòng yêu cầu bạn hoàn thành tờ trình thẩm định tín dụng trước cuộc họp thẩm định, dựa trên hồ sơ được cung cấp.\n\n- Thông tin doanh nghiệp\n\n- Lịch sử tín dụng\n\n- Báo cáo tài chính 2023–2025\n\n- Tài sản đảm bảo đề xuất\n\n- Phương án sử dụng vốn\n\n- Chính sách tín dụng SME của Ngân hàng Đại Dương","requirements":["Nhiệm vụ 1: Điền vào Bảng Thẩm định cho sẵn và Đánh giá chất lượng dòng tiền của doanh nghiệp\n\nNhiệm vụ 2: Đánh giá khả năng trả nợ, nguồn trả nợ, và đối chiếu khoản vay với chính sách tín dụng của Ngân hàng. Xác định 3 rủi ro tín dụng trọng yếu nhất, xếp theo mức độ quan trọng.\n\nNhiệm vụ 3: Quyết định Có/Không cấp tín dụng. Nếu có, đề xuất cụ thể: hạn mức, kỳ hạn, lãi suất và điều kiện đi kèm. Nếu không, nêu lý do và điều kiện để Ngân hàng xem xét lại."],"rubric":[{"criterion_id":"C1","criterion_name":"NHIỆM VỤ 1 –","max_points":35,"source_max_points":35,"description":"NHIỆM VỤ 1 – (35 điểm)\n- Tính 5 chỉ số × 3 năm (20đ): 4đ/chỉ số khi đúng cả 3 năm; đúng 2/3 năm 2,5đ; 1/3 năm 1đ; sai công thức nhưng nhất quán tối đa 50%.\n- Đánh giá đúng chất lượng dòng tiền (15đ)","checklist":[{"checklist_id":"TCNH-02-C1-1","text":"- Tính 5 chỉ số × 3 năm (20đ): 4đ/chỉ số khi đúng cả 3 năm; đúng 2/3 năm 2,5đ; 1/3 năm 1đ; sai công thức nhưng nhất quán tối đa 50%.","points":20,"scoring_source":"ai"},{"checklist_id":"TCNH-02-C1-2","text":"- Đánh giá đúng chất lượng dòng tiền (15đ)","points":15,"scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"NHIỆM VỤ 2 –","max_points":25,"source_max_points":25,