","required":true}],"public_materials":[{"id":"source-3","title":"Thông tin doanh nghiệp","kind":"image","href":"/materials/source-20261017/03.png"},{"id":"source-4","title":"Lịch sử tín dụng","kind":"image","href":"/materials/source-20261017/04.png"},{"id":"source-5","title":"Báo cáo tài chính 2023–2025","kind":"image","href":"/materials/source-20261017/05.png"},{"id":"source-6","title":"Tài sản đảm bảo đề xuất","kind":"image","href":"/materials/source-20261017/06.png"},{"id":"source-7","title":"Phương án sử dụng vốn","kind":"image","href":"/materials/source-20261017/07.png"},{"id":"source-8","title":"Chính sách tín dụng SME của Ngân hàng Đại Dương","kind":"image","href":"/materials/source-20261017/08.png"},{"id":"credit-table-1","title":"Bảng 1: Tính các chỉ số yêu cầu trong 3 năm (đơn vị theo ghi chú)","kind":"table","columns":["Chỉ số","Năm 2023","Năm 2024","Năm 2025"],"rows":[["D/E = Tổng nợ phải trả / VCSH","","",""],["ICR = EBIT / lãi vay","","",""],["Biên lợi nhuận ròng","","",""],["ROA (số dư cuối năm)","","",""],["ROE (số dư cuối năm)","","",""]],"editable":true,"href":"/materials/source-20261017/credit-table-1.png"},{"id":"credit-table-2","title":"Bảng 2: Tính các chỉ số yêu cầu trong 3 năm","kind":"table","columns":["Chỉ số","Năm 2023","Năm 2024","Năm 2025","Ý nghĩa"],"rows":[["Tăng trưởng doanh thu","","","",""],["Tăng trưởng giá vốn","","","",""],["Biên gộp","","","",""],["Biên EBITDA","","","",""],["Tăng trưởng LNST","","","",""],["Hệ số thanh toán hiện hành","","","",""],["Nợ vay/EBITDA","","","",""],["Số ngày phải thu / tồn kho","","","",""],["Dòng tiền tự do (CFO + dòng tiền đầu tư), tỷ đồng","","","",""],["Cổ tức hàm ý từ biến động VCSH, tỷ đồng","","","",""]],"editable":true,"href":"/materials/source-20261017/credit-table-2.png"}],"source_rubric_text":"NHIỆM VỤ 1 – (35 điểm)\n\n- Tính 5 chỉ số × 3 năm (20đ): 4đ/chỉ số khi đúng cả 3 năm; đúng 2/3 năm 2,5đ; 1/3 năm 1đ; sai công thức nhưng nhất quán tối đa 50%.\n\n- Đánh giá đúng chất lượng dòng tiền (15đ)\n\nNHIỆM VỤ 2 – (25 điểm)\n\n- Khả năng trả nợ & tuân thủ chính sách (10đ): Đánh giá proforma vay 5 tỷ qua D/E, ICR, Nợ vay/EBITDA, tỷ lệ tài trợ và TSBĐ; so sánh phương án vay 3 tỷ.\n\n- Nêu 3 rủi ro có số liệu, xếp theo mức độ ưu tiên (15đ)\n\nNHIỆM VỤ 3 - (30đ)\n\n- Quyết định tín dụng (20đ): Quyết định cho vay/từ chối nhất quán với phân tích. Thiếu giải thích: tối đa 5đ\n\n+ Cấp tín dụng: Đề xuất hạn mức ≤ 4,9 tỷ, kỳ hạn ≤ 60 tháng, ân hạn khoảng 12 tháng, lãi suất 9–10% và nguồn trả nợ.\n\n+ Từ chối, nêu căn cứ và lộ trình xem xét lại.\n\n- Điều kiện kèm theo (10đ): Đề xuất ít nhất 4 điều kiện phù hợp với rủi ro\n\nTRÌNH BÀY (10đ)","grading_ready":true,"source_conflicts":[],"source_total_points":100,"source_snapshot":"source/simulations-20261019.json","source_location":{"tab_id":"t.a9gvxnc5ma1m","table_index":53,"row_index":1},"artifacts":{"TCNH-02-DATA-01":{"artifact_id":"TCNH-02-DATA-01","position_id":"TCNH-02","source_version":"20261017","documents":{"company_information":{"source_image":"03.png","rows":[["Tên doanh nghiệp","Công ty Cổ phần Con Sứa"],["Mã số thuế","0312 345 678"],["Giấy phép kinh doanh","Số 0123456789, cấp ngày 15/03/2015"],["Vốn điều lệ","15.000.000.000 đồng"],["Ngành nghề chính","Chế biến, bảo quản và xuất khẩu thủy sản (mã ngành 1020)"],["Số năm hoạt động","11 năm (thành lập 2015)"],["Địa điểm hoạt động","Khu công nghiệp ven biển, khu vực Bà Rịa – Vũng Tàu cũ, TP. Hồ Chí Minh"],["Số lao động","85 người (73 người năm 2024; 62 người năm 2023)"],["Thị trường xuất khẩu","Nhật Bản (60%), Hàn Quốc (25%), EU (15%)"],["Ban lãnh đạo","Ông Lê Văn Trà - Chủ tịch HĐQT, sở hữu 55% vốn (10 năm kinh nghiệm ngành); Bà Trần Thị Thanh Nhàn – Tổng Giám đốc (12 năm kinh nghiệm)"]]},"credit_history":{"source_image":"04.png","rows":[["Quan hệ tín dụng hiện hữu","Đang vay tại 2 tổ chức tín dụng khác, tổng dư nợ 20,2 tỷ đồng (31/12/2025): Ngân hàng A 12,0 tỷ (vay đầu tư và vốn lưu động, thế chấp nhà xưởng và máy móc hiện hữu); Ngân hàng B 8,2 tỷ (vốn lưu động, thế chấp một phần hàng tồn kho)."],["Phân loại nợ theo CIC (36 tháng gần nhất)","Nhóm 1 (đủ tiêu chuẩn) tại tất cả các kỳ báo cáo."],["Ghi nhận bất thường","Tháng 08/2025: chậm trả lãi 12 ngày tại Ngân hàng B, đã tất toán đầy đủ."],["Quan hệ với Ngân hàng Đại Dương","Có tài khoản thanh toán từ năm 2019, chưa có dư nợ. Doanh số qua tài khoản năm 2025: 40 tỷ đồng (khoảng 38% doanh thu)."],["Nghĩa vụ với Nhà nước","Chưa ghi nhận nợ đọng thuế hoặc bảo hiểm xã hội."]]},"financial_statements":{"source_image":"05.png","columns":["Chỉ tiêu","Năm 2023","Năm 2024","Năm 2025"],"rows":[["Tổng tài sản","42,5","49,8","58,5"],["Tài sản ngắn hạn","24,0","28,5","33,0"],["Tiền và tương đương tiền","3,9","4,7","3,8"],["Phải thu ngắn hạn","9,5","11,5","14,0"],["Hàng tồn kho","9,8","11,5","14,4"],["Tài sản ngắn hạn khác","0,8","0,8","0,8"],["Tài sản dài hạn","18,5","21,3","25,5"],["Tổng nợ phải trả","22,3","28,7","38,2"],["Nợ ngắn hạn","14,5","18,2","23,5"],["Trong đó: vay ngắn hạn","4,5","5,5","9,7"],["Nợ dài hạn","7,8","10,5","14,7"],["Trong đó: vay dài hạn","6,5","8,0","10,5"],["Vốn chủ sở hữu (VCSH)","20,2","21,1","20,3"],["Doanh thu thuần","72,3","88,5","105,2"],["Giá vốn hàng bán","57,8","71,8","87,3"],["Lợi nhuận gộp","14,5","16,7","17,9"],["Biên lợi nhuận gộp","20,1%","18,9%","17,0%"],["Chi phí bán hàng và quản lý doanh nghiệp","7,9","9,5","11,8"],["EBITDA","6,6","7,2","6,1"],["Khấu hao","2,4","2,9","2,9"],["Chi phí lãi vay","1,0","1,5","1,7"],["Lợi nhuận trước thuế (LNTT)","3,2","2,8","1,5"],["Thuế thu nhập doanh nghiệp (đã làm tròn)","0,6","0,6","0,4"],["Lợi nhuận sau thuế (LNST)","2,6","2,2","1,1"],["Dòng tiền từ hoạt động kinh doanh (CFO)","4,2","3,1","(1,5)"],["Dòng tiền từ hoạt động đầu tư","(2,8)","(3,5)","(4,2)"],["Dòng tiền từ hoạt động tài chính","(0,5)","1,2","4,8"],["Tiền và tương đương tiền cuối năm","3,9","4,7","3,8"],["D/E (Tổng nợ phải trả / VCSH)","1,10","1,36","1,88"],["ICR (EBIT / Chi phí lãi vay)","4,6","3,5","2,4"],["Biên lợi nhuận ròng (LNST / Doanh thu thuần)","3,6%","2,5%","1,0%"],["ROA (LNST / Tổng tài sản cuối năm)","6,1%","4,4%","1,9%"],["ROE (LNST / VCSH cuối năm)","12,9%","10,4%","5,4%"]]},"collateral":{"source_image":"06.png","columns":["Tài sản","Giá trị","Ghi chú"],"rows":[["Nhà kho lạnh và quyền thuê đất tại khu công nghiệp","4,0","Giá trị do đơn vị thẩm định giá độc lập xác định. Chưa thế chấp tại tổ chức tín dụng khác. Thời hạn thuê đất còn lại 28 năm."],["Dây chuyền cấp đông mới (hình thành từ vốn vay)","4,5","Giá theo báo giá nhà cung cấp. Thế chấp sau khi lắp đặt; dự kiến khấu hao 8 năm."],["Máy móc, nhà xưởng hiện hữu","–","Đã thế chấp tại Ngân hàng A, không dùng làm tài sản đảm bảo cho khoản vay này."]]},"loan_use":{"source_image":"07.png","rows":[["Mục tiêu","Tăng 30% công suất cấp đông phục vụ đơn hàng xuất khẩu."],["Tổng nhu cầu vốn","7,0 tỷ đồng, gồm: mua dây chuyền cấp đông 4,5 tỷ; bổ sung vốn lưu động (nguyên liệu) 2,5 tỷ."],["Nguồn vốn","Vay Ngân hàng Đại Dương 5,0 tỷ; vốn tự có 2,0 tỷ (từ tiền mặt hiện có)."],["Đề nghị của doanh nghiệp","Kỳ hạn 5 năm (60 tháng); ân hạn gốc 12 tháng; trả gốc đều hàng quý sau ân hạn; trả lãi hàng tháng; lãi suất đề nghị 8,0%/năm."],["Nguồn trả nợ dự kiến","Dòng tiền hoạt động kinh doanh của doanh nghiệp và của dây chuyền mới."]],"unverified_projection":{"unit":"tỷ đồng","columns":["Chỉ tiêu","Năm 1","Năm 2","Năm 3"],"rows":[["Doanh thu tăng thêm","10,0","25,0","30,0"],["EBITDA tăng thêm","0,5","2,0","2,7"]]}},"bank_policy":{"source_image":"08.png","rows":[["Lãi suất cho vay trung hạn","Lãi suất cơ sở 6,5%/năm cộng biên độ rủi ro theo xếp hạng nội bộ: hạng A: 1,5%; hạng B: 2,5%; hạng C: 3,5%; hạng D: không cho vay. Thẩm định viên đề xuất hạng."],["Kỳ hạn tối đa","Vay đầu tư máy móc thiết bị: 60 tháng. Vay bổ sung vốn lưu động trung hạn: tối đa 12 tháng."],["Tỷ lệ vay tối đa","Không quá 70% tổng nhu cầu vốn của phương án."],["Tỷ lệ cho vay tối đa so với giá trị tài sản đảm bảo (LTV)","Nhà xưởng, quyền sử dụng đất: 70%. Máy móc thiết bị: 50%. Hàng tồn kho: 30%. Tổng giá trị cho vay tối đa theo tài sản đảm bảo phải không thấp hơn dư nợ đề xuất."],["Ngưỡng tài chính tối thiểu khi cấp mới","D/E (tổng nợ/VCSH) không quá 2,5 lần; ICR không thấp hơn 2,0 lần; Hệ số thanh toán hiện hành không thấp hơn 1,2 lần; Nợ vay/EBITDA không quá 4,0 lần."],["Ngoại lệ","Khoản vay không đạt ngưỡng phải có biện pháp giảm thiểu rủi ro tương ứng và được cấp có thẩm quyền phê duyệt."]]}},"source_inconsistencies":[{"source_image":"05.png","issue":"ICR nguồn cho sẵn 4,6 / 3,5 / 2,4 không khớp EBIT=(EBITDA-khấu hao) chia chi phí lãi vay từ cùng bảng: 4,2 / 2,866666... / 1,8823529... . Giữ nguyên dữ liệu gốc; không tự sửa hoặc phạt ứng viên khi họ chỉ ra mâu thuẫn này."}]}}}'::jsonb where id = 'ba8324f6-e997-53d8-a0c8-7a77f920c841' and slug = 'r2w-tcnh-02';
update public.simulation_attempts a set superseded_at = now() from public.simulations s where a.simulation_id = s.id and s.id = '0878eafa-018f-522f-bb00-55a103af253d' and a.submission_id is null and a.superseded_at is null and coalesce(s.reference_data->>'content_revision', '') <> '20261019-simulations';
update public.simulations set brief = 'Bạn là chuyên viên phân tích rủi ro tín dụng tại Ngân hàng Đáy Biển. Phòng Quan hệ khách hàng đề xuất khoản vay trung hạn 400 tỷ đồng cho Công ty Cổ phần Con Cua xây dựng giai đoạn 2 nhà máy thép tại Hưng Yên. Trước biến động giá nguyên liệu và cạnh tranh từ thép nhập khẩu, bạn cần phân tích hồ sơ, đánh giá rủi ro và đưa ra ý kiến độc lập trình Hội đồng Tín dụng

- Hồ sơ đề xuất cấp tín dụng và thông tin dự án

- Báo cáo tài chính tóm tắt năm 2025 (đơn vị: tỷ đồng)

- Bản tin ngành thép và chỉ số trung vị ngành (số liệu mô phỏng)

- Chính sách và khẩu vị rủi ro tín dụng của Ngân hàng Đại Dương',
  task_instructions = '## Bối cảnh

Bạn là chuyên viên phân tích rủi ro tín dụng tại Ngân hàng Đáy Biển. Phòng Quan hệ khách hàng đề xuất khoản vay trung hạn 400 tỷ đồng cho Công ty Cổ phần Con Cua xây dựng giai đoạn 2 nhà máy thép tại Hưng Yên. Trước biến động giá nguyên liệu và cạnh tranh từ thép nhập khẩu, bạn cần phân tích hồ sơ, đánh giá rủi ro và đưa ra ý kiến độc lập trình Hội đồng Tín dụng

- Hồ sơ đề xuất cấp tín dụng và thông tin dự án

- Báo cáo tài chính tóm tắt năm 2025 (đơn vị: tỷ đồng)

- Bản tin ngành thép và chỉ số trung vị ngành (số liệu mô phỏng)

- Chính sách và khẩu vị rủi ro tín dụng của Ngân hàng Đại Dương

## Yêu cầu nhiệm vụ

Nhiệm vụ 1: Điền vào bảng cho sẵn và nhận xét D/E (trước và sau giải ngân), hệ số thanh toán hiện hành, các biên lợi nhuận, khả năng trả lãi (ICR) và Nợ vay/EBITDA; so sánh với trung vị ngành và khẩu vị rủi ro của Ngân hàng; kết luận mức rủi ro tổng hợp (cao, trung bình hoặc thấp).

Nhiệm vụ 2:

- Phân tích rủi ro về ngành, yếu tố vĩ mô và đặc thù của dự án.

- Đề xuất ít nhất 3 biện pháp bảo vệ Ngân hàng và giải thích cơ chế bảo vệ của từng biện pháp.

Nhiệm vụ 3:

- Viết báo cáo ngắn (tối đa 200 từ) gửi Hội đồng Tín dụng với kết luận: Đồng ý cho vay, Cho vay có điều kiện hoặc Từ chối. Nêu lý do kèm số liệu.

Báo cáo 200 từ được đếm theo số từ tách bởi khoảng trắng; khung nhập báo cáo có bộ đếm từ.',
  is_available = true,
  unavailable_reason = null,
  rubric = '[{"id":"C1","label":"NHIỆM VỤ 1 –","weight":30,"maxScore":30},{"id":"C2","label":"NHIỆM VỤ 2 –","weight":30,"maxScore":30},{"id":"C3","label":"NHIỆM VỤ 3 - Viết báo","weight":30,"maxScore":30},{"id":"C4","label":"TRÌNH BÀY","weight":10,"maxScore":10}]'::jsonb,
  grading_rubric = '[{"id":"C1","label":"NHIỆM VỤ 1 –","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-03-C1-1\",\"text\":\"- D/E (4đ): D/E 4,2 (kiểm tra 1.680/400) vượt ngưỡng 3,0 và gấp đôi trung vị ngành 2,0. Sau giải ngân 5,2 (2.080/400). Nếu tăng vốn 150 tỷ: 3,78, vẫn vượt ngưỡng. Nhận xét khả năng chịu thêm nợ.\",\"points\":4,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C1-2\",\"text\":\"- Thanh khoản (4đ):Hệ số 0,85 (1.020/1.200) < 1,0; thiếu hụt vốn lưu động 180 tỷ; dưới trung vị ngành 1,1; nợ vay ngắn hạn 780 tỷ phải tái cấp.\",\"points\":4,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C1-3\",\"text\":\"- Biên lợi nhuận (4đ): Biên gộp 12,4% và EBITDA 9,8% cao hơn trung vị ngành (11,0% và 8,0%), nhưng biên ròng 2,1% thấp hơn trung vị 3,0%: vấn đề nằm ở chi phí tài chính chứ không ở hiệu quả vận hành.\",\"points\":4,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C1-4\",\"text\":\"- Khả năng trả nợ (4đ): ICR = 183/118 = 1,55 (dưới 2,0), lãi vay ăn khoảng 64% EBIT; sau khoản vay trong giai đoạn xây dựng ICR còn khoảng 1,20; Nợ vay/EBITDA 6,86 → 8,49 (ngưỡng 4,5), còn khoảng 6,0 khi dự án đạt công suất.\",\"points\":4,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C1-5\",\"text\":\"- Kết luận mức rủi ro lập luận từ chỉ số (4đ)\\n⇒ đáp án bảng\",\"points\":4,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C1-6\",\"text\":\"- Đánh giá đúng chất lượng dòng tiền (10đ)\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C2","label":"NHIỆM VỤ 2 –","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-03-C2-1\",\"text\":\"- Nếu được 3 rủi ro ngành (10đ):\\nBiến động giá quặng sắt, than cốc ép biên\\nCạnh tranh thép nhập khẩu giá rẻ\\ncông suất ngành vượt cầu\\nphụ thuộc đầu tư công và bất động sản\\nlãi suất 8–9% tăng chi phí vay thả nổi.\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C2-2\",\"text\":\"- Nêu được 3 rủi ro dự án (10đ)\\nVốn đối ứng 150 tỷ chưa góp, chưa có bảo lãnh.\\n24 tháng xây dựng chưa có dòng tiền dự án.\\nTài sản đảm bảo chỉ hình thành dần\\nTập trung ngành: 7,5% → 7,96% sát trần 8%.\\nNợ xấu danh mục thép 2,0% nhưng nếu khoản 400 tỷ vỡ nợ thì tăng lên khoảng 8,1%\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C2-3\",\"text\":\"- Nêu cơ chế bảo vệ ngân hàng và giải thích (10đ):\\nNêu ít nhất 3 biện pháp + cơ chế. Ví dụ: giải ngân theo tiến độ, trả thẳng nhà cung cấp; tài sản đảm bảo bổ sung và LTV theo từng đợt, …\\nChỉ nêu tên không chỉ ra cơ chế: 3đ/ biện\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C3","label":"NHIỆM VỤ 3 - Viết báo","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-03-C3-1\",\"text\":\"- Cấu trúc báo cáo (10đ): Có tiêu đề, người nhận, mở đầu và kết thúc.\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C3-2\",\"text\":\"- Khuyến nghị rõ (5đ): đồng ý, có điều kiện, từ chối.\",\"points\":5,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C3-3\",\"text\":\"- Lý do có số liệu (10đ):Lý do khớp phần phân tích, có số liệu\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"TCNH-03-C3-4\",\"text\":\"- Súc tích (tối đa 200 từ) (5đ): Đúng giới hạn, không lan man.\",\"points\":5,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":30,"maxScore":30},{"id":"C4","label":"TRÌNH BÀY","description":"{\"checklist\":[{\"checklist_id\":\"TCNH-03-C4-1\",\"text\":\"TRÌNH BÀY (10đ)\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":10,"maxScore":10}]'::jsonb,
  reference_data = '{"position_id":"TCNH-03","position_name":"Risk Analyst (Chuyên viên Phân tích Rủi ro tín dụng)","level":"Fresher/Junior","time_limit_minutes":60,"time_limit_source":"not_specified","source_version":"20261019","source_policy":"document_only","content_revision":"20261019-simulations","source_block":441,"context":"Bạn là chuyên viên phân tích rủi ro tín dụng tại Ngân hàng Đáy Biển. Phòng Quan hệ khách hàng đề xuất khoản vay trung hạn 400 tỷ đồng cho Công ty Cổ phần Con Cua xây dựng giai đoạn 2 nhà máy thép tại Hưng Yên. Trước biến động giá nguyên liệu và cạnh tranh từ thép nhập khẩu, bạn cần phân tích hồ sơ, đánh giá rủi ro và đưa ra ý kiến độc lập trình Hội đồng Tín dụng\n\n- Hồ sơ đề xuất cấp tín dụng và thông tin dự án\n\n- Báo cáo tài chính tóm tắt năm 2025 (đơn vị: tỷ đồng)\n\n- Bản tin ngành thép và chỉ số trung vị ngành (số liệu mô phỏng)\n\n- Chính sách và khẩu vị rủi ro tín dụng của Ngân hàng Đại Dương","requirements":["Nhiệm vụ 1: Điền vào bảng cho sẵn và nhận xét D/E (trước và sau giải ngân), hệ số thanh toán hiện hành, các biên lợi nhuận, khả năng trả lãi (ICR) và Nợ vay/EBITDA; so sánh với trung vị ngành và khẩu vị rủi ro của Ngân hàng; kết luận mức rủi ro tổng hợp (cao, trung bình hoặc thấp).\n\nNhiệm vụ 2:\n\n- Phân tích rủi ro về ngành, yếu tố vĩ mô và đặc thù của dự án.\n\n- Đề xuất ít nhất 3 biện pháp bảo vệ Ngân hàng và giải thích cơ chế bảo vệ của từng biện pháp.\n\nNhiệm vụ 3:\n\n- Viết báo cáo ngắn (tối đa 200 từ) gửi Hội đồng Tín dụng với kết luận: Đồng ý cho vay, Cho vay có điều kiện hoặc Từ chối. Nêu lý do kèm số liệu.\n\nBáo cáo 200 từ được đếm theo số từ tách bởi khoảng trắng; khung nhập báo cáo có bộ đếm từ."],"rubric":[{"criterion_id":"C1","criterion_name":"NHIỆM VỤ 1 –","max_points":30,"source_max_points":30,"description":"NHIỆM VỤ 1 – (30 điểm)\n- D/E (4đ): D/E 4,2 (kiểm tra 1.680/400) vượt ngưỡng 3,0 và gấp đôi trung vị ngành 2,0. Sau giải ngân 5,2 (2.080/400). Nếu tăng vốn 150 tỷ: 3,78, vẫn vượt ngưỡng. Nhận xét khả năng chịu thêm nợ.\n- Thanh khoản (4đ):Hệ số 0,85 (1.020/1.200) < 1,0; thiếu hụt vốn lưu động 180 tỷ; dưới trung vị ngành 1,1; nợ vay ngắn hạn 780 tỷ phải tái cấp.\n- Biên lợi nhuận (4đ): Biên gộp 12,4% và EBITDA 9,8% cao hơn trung vị ngành (11,0% và 8,0%), nhưng biên ròng 2,1% thấp hơn trung vị 3,0%: vấn đề nằm ở chi phí tài chính chứ không ở hiệu quả vận hành.\n- Khả năng trả nợ (4đ): ICR = 183/118 = 1,55 (dưới 2,0), lãi vay ăn khoảng 64% EBIT; sau khoản vay trong giai đoạn xây dựng ICR còn khoảng 1,20; Nợ vay/EBITDA 6,86 → 8,49 (ngưỡng 4,5), còn khoảng 6,0 khi dự án đạt công suất.\n- Kết luận mức rủi ro lập luận từ chỉ số (4đ)\n⇒ đáp án bảng\n- Đánh giá đúng chất lượng dòng tiền (10đ)","checklist":[{"checklist_id":"TCNH-03-C1-1","text":"- D/E (4đ): D/E 4,2 (kiểm tra 1.680/400) vượt ngưỡng 3,0 và gấp đôi trung vị ngành 2,0. Sau giải ngân 5,2 (2.080/400). Nếu tăng vốn 150 tỷ: 3,78, vẫn vượt ngưỡng. Nhận xét khả năng chịu thêm nợ.","points":4,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C1-2","text":"- Thanh khoản (4đ):Hệ số 0,85 (1.020/1.200) < 1,0; thiếu hụt vốn lưu động 180 tỷ; dưới trung vị ngành 1,1; nợ vay ngắn hạn 780 tỷ phải tái cấp.","points":4,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C1-3","text":"- Biên lợi nhuận (4đ): Biên gộp 12,4% và EBITDA 9,8% cao hơn trung vị ngành (11,0% và 8,0%), nhưng biên ròng 2,1% thấp hơn trung vị 3,0%: vấn đề nằm ở chi phí tài chính chứ không ở hiệu quả vận hành.","points":4,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C1-4","text":"- Khả năng trả nợ (4đ): ICR = 183/118 = 1,55 (dưới 2,0), lãi vay ăn khoảng 64% EBIT; sau khoản vay trong giai đoạn xây dựng ICR còn khoảng 1,20; Nợ vay/EBITDA 6,86 → 8,49 (ngưỡng 4,5), còn khoảng 6,0 khi dự án đạt công suất.","points":4,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C1-5","text":"- Kết luận mức rủi ro lập luận từ chỉ số (4đ)\n⇒ đáp án bảng","points":4,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C1-6","text":"- Đánh giá đúng chất lượng dòng tiền (10đ)","points":10,"scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"NHIỆM VỤ 2 –","max_points":30,"source_max_points":30,"description":"NHIỆM VỤ 2 – (30 điểm)\n- Nếu được 3 rủi ro ngành (10đ):\nBiến động giá quặng sắt, than cốc ép biên\nCạnh tranh thép nhập khẩu giá rẻ\ncông suất ngành vượt cầu\nphụ thuộc đầu tư công và bất động sản\nlãi suất 8–9% tăng chi phí vay thả nổi.\n- Nêu được 3 rủi ro dự án (10đ)\nVốn đối ứng 150 tỷ chưa góp, chưa có bảo lãnh.\n24 tháng xây dựng chưa có dòng tiền dự án.\nTài sản đảm bảo chỉ hình thành dần\nTập trung ngành: 7,5% → 7,96% sát trần 8%.\nNợ xấu danh mục thép 2,0% nhưng nếu khoản 400 tỷ vỡ nợ thì tăng lên khoảng 8,1%\n- Nêu cơ chế bảo vệ ngân hàng và giải thích (10đ):\nNêu ít nhất 3 biện pháp + cơ chế. Ví dụ: giải ngân theo tiến độ, trả thẳng nhà cung cấp; tài sản đảm bảo bổ sung và LTV theo từng đợt, …\nChỉ nêu tên không chỉ ra cơ chế: 3đ/ biện","checklist":[{"checklist_id":"TCNH-03-C2-1","text":"- Nếu được 3 rủi ro ngành (10đ):\nBiến động giá quặng sắt, than cốc ép biên\nCạnh tranh thép nhập khẩu giá rẻ\ncông suất ngành vượt cầu\nphụ thuộc đầu tư công và bất động sản\nlãi suất 8–9% tăng chi phí vay thả nổi.","points":10,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C2-2","text":"- Nêu được 3 rủi ro dự án (10đ)\nVốn đối ứng 150 tỷ chưa góp, chưa có bảo lãnh.\n24 tháng xây dựng chưa có dòng tiền dự án.\nTài sản đảm bảo chỉ hình thành dần\nTập trung ngành: 7,5% → 7,96% sát trần 8%.\nNợ xấu danh mục thép 2,0% nhưng nếu khoản 400 tỷ vỡ nợ thì tăng lên khoảng 8,1%","points":10,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C2-3","text":"- Nêu cơ chế bảo vệ ngân hàng và giải thích (10đ):\nNêu ít nhất 3 biện pháp + cơ chế. Ví dụ: giải ngân theo tiến độ, trả thẳng nhà cung cấp; tài sản đảm bảo bổ sung và LTV theo từng đợt, …\nChỉ nêu tên không chỉ ra cơ chế: 3đ/ biện","points":10,"scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"NHIỆM VỤ 3 - Viết báo","max_points":30,"source_max_points":30,"description":"NHIỆM VỤ 3 - Viết báo  (30đ)\n- Cấu trúc báo cáo (10đ): Có tiêu đề, người nhận, mở đầu và kết thúc.\n- Khuyến nghị rõ (5đ): đồng ý, có điều kiện, từ chối.\n- Lý do có số liệu (10đ):Lý do khớp phần phân tích, có số liệu\n- Súc tích (tối đa 200 từ) (5đ): Đúng giới hạn, không lan man.","checklist":[{"checklist_id":"TCNH-03-C3-1","text":"- Cấu trúc báo cáo (10đ): Có tiêu đề, người nhận, mở đầu và kết thúc.","points":10,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C3-2","text":"- Khuyến nghị rõ (5đ): đồng ý, có điều kiện, từ chối.","points":5,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C3-3","text":"- Lý do có số liệu (10đ):Lý do khớp phần phân tích, có số liệu","points":10,"scoring_source":"ai"},{"checklist_id":"TCNH-03-C3-4","text":"- Súc tích (tối đa 200 từ) (5đ): Đúng giới hạn, không lan man.","points":5,"scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"TRÌNH BÀY","max_points":10,"source_max_points":10,"description":"TRÌNH BÀY (10đ)","checklist":[{"checklist_id":"TCNH-03-C4-1","text":"TRÌNH BÀY (10đ)","points":10,"scoring_source":"ai"}]}],"hard_constraints":[],"input_artifacts":[{"artifact_id":"TCNH-03-DATA-01","type":"source_documents","description":"Bộ hồ sơ gốc đính kèm trong đề bài.","required":true}],"public_materials":[{"id":"source-15","title":"Hồ sơ đề xuất cấp tín dụng và thông tin dự án","kind":"image","href":"/materials/source-20261017/15.png"},{"id":"source-16","title":"Báo cáo tài chính tóm tắt năm 2025 (đơn vị: tỷ đồng)","kind":"image","href":"/materials/source-20261017/16.png"},{"id":"source-17","title":"Bản tin ngành thép và chỉ số trung vị ngành","kind":"image","href":"/materials/source-20261017/17.png"},{"id":"source-18","title":"Chính sách và khẩu vị rủi ro tín dụng của Ngân hàng Đại Dương","kind":"image","href":"/materials/source-20261017/18.png"},{"id":"risk-table","title":"Bảng chỉ số tài chính","kind":"table","columns":["Chỉ số","Giá trị","Ngưỡng Ngân hàng","Trung vị ngành"],"rows":[["D/E (nợ vay/VCSH) hiện tại","","",""],["D/E sau giải ngân 400 tỷ","","",""],["D/E sau giải ngân nếu tăng vốn 150 tỷ","","",""],["Hệ số thanh toán hiện hành","","",""],["Biên gộp / EBITDA / ròng","","",""],["ICR hiện tại (EBIT 183 / lãi vay 118)","","",""],["ICR trong giai đoạn xây dựng (lãi vay thêm 34 tỷ)","","",""],["Lãi vay / EBIT","","",""],["Nợ vay/EBITDA hiện tại / sau giải ngân / khi đạt công suất","","",""]],"editable":true,"href":"/materials/source-20261017/19.png"}],"source_rubric_text":"NHIỆM VỤ 1 – (30 điểm)\n\n- D/E (4đ): D/E 4,2 (kiểm tra 1.680/400) vượt ngưỡng 3,0 và gấp đôi trung vị ngành 2,0. Sau giải ngân 5,2 (2.080/400). Nếu tăng vốn 150 tỷ: 3,78, vẫn vượt ngưỡng. Nhận xét khả năng chịu thêm nợ.\n\n- Thanh khoản (4đ):Hệ số 0,85 (1.020/1.200) < 1,0; thiếu hụt vốn lưu động 180 tỷ; dưới trung vị ngành 1,1; nợ vay ngắn hạn 780 tỷ phải tái cấp.\n\n- Biên lợi nhuận (4đ): Biên gộp 12,4% và EBITDA 9,8% cao hơn trung vị ngành (11,0% và 8,0%), nhưng biên ròng 2,1% thấp hơn trung vị 3,0%: vấn đề nằm ở chi phí tài chính chứ không ở hiệu quả vận hành.\n\n- Khả năng trả nợ (4đ): ICR = 183/118 = 1,55 (dưới 2,0), lãi vay ăn khoảng 64% EBIT; sau khoản vay trong giai đoạn xây dựng ICR còn khoảng 1,20; Nợ vay/EBITDA 6,86 → 8,49 (ngưỡng 4,5), còn khoảng 6,0 khi dự án đạt công suất.\n\n- Kết luận mức rủi ro lập luận từ chỉ số (4đ)\n\n⇒ đáp án bảng\n\n- Đánh giá đúng chất lượng dòng tiền (10đ)\n\nNHIỆM VỤ 2 – (30 điểm)\n\n- Nếu được 3 rủi ro ngành (10đ):\n\n- Biến động giá quặng sắt, than cốc ép biên\n\n- Cạnh tranh thép nhập khẩu giá rẻ\n\n- công suất ngành vượt cầu\n\n- phụ thuộc đầu tư công và bất động sản\n\n- lãi suất 8–9% tăng chi phí vay thả nổi.\n\n- Nêu được 3 rủi ro dự án (10đ)\n\n- Vốn đối ứng 150 tỷ chưa góp, chưa có bảo lãnh.\n\n- 24 tháng xây dựng chưa có dòng tiền dự án.\n\n- Tài sản đảm bảo chỉ hình thành dần\n\n- Tập trung ngành: 7,5% → 7,96% sát trần 8%.\n\n- Nợ xấu danh mục thép 2,0% nhưng nếu khoản 400 tỷ vỡ nợ thì tăng lên khoảng 8,1%\n\n- Nêu cơ chế bảo vệ ngân hàng và giải thích (10đ):\n\n- Nêu ít nhất 3 biện pháp + cơ chế. Ví dụ: giải ngân theo tiến độ, trả thẳng nhà cung cấp; tài sản đảm bảo bổ sung và LTV theo từng đợt, …\n\n- Chỉ nêu tên không chỉ ra cơ chế: 3đ/ biện\n\nNHIỆM VỤ 3 - Viết báo  (30đ)\n\n- Cấu trúc báo cáo (10đ): Có tiêu đề, người nhận, mở đầu và kết thúc.\n\n- Khuyến nghị rõ (5đ): đồng ý, có điều kiện, từ chối.\n\n- Lý do có số liệu (10đ):Lý do khớp phần phân tích, có số liệu\n\n- Súc tích (tối đa 200 từ) (5đ): Đúng giới hạn, không lan man.\n\nTRÌNH BÀY (10đ)","grading_ready":true,"source_conflicts":[],"source_total_points":100,"source_snapshot":"source/simulations-20261019.json","source_location":{"tab_id":"t.a9gvxnc5ma1m","table_index":53,"row_index":3},"artifacts":{"TCNH-03-DATA-01":{"artifact_id":"TCNH-03-DATA-01","position_id":"TCNH-03","source_version":"20261017","documents":{"project":{"source_image":"15.png","rows":[["Khách hàng","Công ty Cổ phần Con Cua – sản xuất thép xây dựng (thép thanh vằn, thép cuộn)."],["Dự án","Xây dựng giai đoạn 2 nhà máy cán thép tại Khu công nghiệp Phố Nối A, tỉnh Hưng Yên."],["Tổng mức đầu tư","650 tỷ đồng."],["Cơ cấu nguồn vốn","Vay Ngân hàng 400 tỷ đồng (61,5%); vốn đối ứng 250 tỷ đồng (38,5%), gồm: 100 tỷ từ lợi nhuận giữ lại trong 24 tháng xây dựng; 150 tỷ từ tăng vốn cổ phần theo chủ trương đã được Đại hội đồng cổ đông thông qua, chưa thực hiện và chưa có cam kết bảo lãnh phát hành."],["Đề nghị vay","Kỳ hạn 10 năm; ân hạn gốc 24 tháng (thời gian xây dựng); lãi suất dự kiến 8,5%/năm, thả nổi."],["Tiến độ","Xây dựng 24 tháng; vận hành thương mại từ năm thứ 3 với 50% công suất, đạt công suất thiết kế từ năm thứ 4."],["Dự báo của khách hàng (chưa kiểm chứng)","Khi đạt công suất thiết kế: doanh thu tăng thêm 1.000 tỷ đồng/năm; EBITDA tăng thêm 100 tỷ đồng/năm."],["Tài sản đảm bảo đề xuất","Tài sản hình thành từ vốn vay (nhà xưởng, dây chuyền cán thép) giá trị dự kiến khi hoàn thành 520 tỷ đồng; quyền sử dụng đất tại khu công nghiệp 90 tỷ đồng."],["Quan hệ với Ngân hàng","Dư nợ hiện hữu tại Ngân hàng Đại Dương 300 tỷ đồng, nhóm 1 (đã nằm trong tổng nợ vay 1.680 tỷ đồng)."]]},"financial_statements":{"source_image":"16.png","year":2025,"unit":"tỷ đồng","rows":[["Doanh thu thuần","2.500"],["Giá vốn hàng bán","2.190"],["Lợi nhuận gộp","310"],["Chi phí bán hàng và quản lý doanh nghiệp","65"],["EBITDA","245"],["Khấu hao","62"],["Chi phí lãi vay","118"],["Lợi nhuận trước thuế","65"],["Thuế thu nhập doanh nghiệp (20%)","13"],["Lợi nhuận sau thuế","52"],["Tổng tài sản","2.500"],["Tài sản ngắn hạn","1.020"],["Tài sản dài hạn","1.480"],["Tổng nợ phải trả","2.100"],["Nợ ngắn hạn","1.200","Gồm vay ngắn hạn 780"],["Nợ dài hạn","900","Toàn bộ là vay dài hạn"],["Tổng nợ vay","1.680","780 ngắn hạn + 900 dài hạn"],["Vốn chủ sở hữu","400"],["Hệ số nợ vay/VCSH (D/E)","4,2","Sinh viên cần kiểm tra lại"],["Hệ số thanh toán hiện hành","0,85","Sinh viên cần kiểm tra lại"]]},"industry":{"source_image":"17.png","facts":["Giá quặng sắt và than cốc biến động mạnh, dao động khoảng ±20% trong 12 tháng gần nhất; nhà sản xuất khó chuyển hết chi phí tăng sang giá bán.","Thép nhập khẩu giá rẻ từ Trung Quốc gia tăng, tạo áp lực giảm giá thép xây dựng trong nước.","Công suất thép xây dựng trong nước đang cao hơn nhu cầu; tiêu thụ nội địa tăng khoảng 3–4%/năm, phụ thuộc vào đầu tư công và thị trường bất động sản.","Lãi suất cho vay trung và dài hạn bình quân của hệ thống ở mức 8–9%/năm."],"median_table_simulated":[["D/E (nợ vay/VCSH)","2,0 lần"],["Hệ số thanh toán hiện hành","1,1 lần"],["Biên lợi nhuận gộp","11,0%"],["Biên EBITDA","8,0%"],["Biên lợi nhuận ròng","3,0%"],["ICR (EBIT/lãi vay)","3,0 lần"]]},"bank_policy":{"source_image":"18.png","rows":[["Ngưỡng tài chính khi cấp tín dụng dự án","D/E (nợ vay/VCSH) không quá 3,0 lần; Hệ số thanh toán hiện hành không thấp hơn 1,0 lần; ICR không thấp hơn 2,0 lần; Nợ vay/EBITDA không quá 4,5 lần."],["Cấu trúc dự án","Vốn đối ứng tối thiểu 30% tổng mức đầu tư và phải được góp hoặc cam kết bảo đảm trước giải ngân. Tỷ lệ cho vay trên giá trị tài sản đảm bảo (LTV) tối đa 70%."],["Chất lượng danh mục thép","Dư nợ ngành thép hiện tại 6.000 tỷ đồng trên tổng dư nợ 80.000 tỷ của Ngân hàng. Tỷ lệ nợ xấu (nhóm 3–5) của danh mục cho vay ngành thép: 2,0%. Ngưỡng chấp nhận của Ngân hàng: 3,0%."],["Giới hạn tập trung ngành","Dư nợ một ngành không quá 8,0% tổng dư nợ."],["Giới hạn một khách hàng","Không quá 15% vốn tự có của Ngân hàng (vốn tự có: 12.000 tỷ đồng)."]]}},"source_inconsistencies":[]}}}'::jsonb where id = '0878eafa-018f-522f-bb00-55a103af253d' and slug = 'r2w-tcnh-03';
